const p = msg.payload;
const topicMatch = /^fleet\/vehicles\/([^/]+)\/telemetry$/.exec(msg.topic || '');
const errors = [];

if (!p || typeof p !== 'object' || Array.isArray(p)) {
  errors.push('payload must be a JSON object');
} else {
  if (typeof p.vehicleId !== 'string' || !p.vehicleId) errors.push('vehicleId is required');
  if (topicMatch && p.vehicleId && topicMatch[1] !== p.vehicleId) errors.push('vehicleId does not match topic');
  if (!Number.isFinite(p.lat) || p.lat < -90 || p.lat > 90) errors.push('lat must be between -90 and 90');
  if (!Number.isFinite(p.lon) || p.lon < -180 || p.lon > 180) errors.push('lon must be between -180 and 180');
  if (!Number.isFinite(p.speedKmh) || p.speedKmh < 0) errors.push('speedKmh must be a non-negative number');
  if (!Number.isFinite(p.batteryPct) || p.batteryPct < 0 || p.batteryPct > 100) errors.push('batteryPct must be between 0 and 100');
  if (typeof p.status !== 'string' || !['idle', 'to_pickup', 'occupied', 'offline'].includes(p.status)) errors.push('status is invalid');
  if (!p.timestamp || Number.isNaN(Date.parse(p.timestamp))) errors.push('timestamp must be an ISO timestamp');
}

msg.validation = { valid: errors.length === 0, errors, receivedAt: new Date().toISOString(), monitorOnly: true };
return errors.length === 0 ? [msg, null] : [null, msg];
